CREATE TABLE IF NOT EXISTS institutions(id text PRIMARY KEY, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Kolkata');
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), name text NOT NULL, email text NOT NULL UNIQUE, role text NOT NULL, department text, student_id text, active boolean NOT NULL DEFAULT true, UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS auth_sessions(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS masters(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), kind text NOT NULL, name text NOT NULL, code text NOT NULL, retired boolean NOT NULL DEFAULT false, UNIQUE(institution_id,kind,code));
CREATE TABLE IF NOT EXISTS policies(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), name text NOT NULL, kind text NOT NULL, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'Draft', effective_date date NOT NULL, config jsonb NOT NULL, owner_id text NOT NULL REFERENCES users(id), approver_id text REFERENCES users(id), UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS students(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), number text NOT NULL, name text NOT NULL, email text NOT NULL, programme text NOT NULL, batch text NOT NULL, department text NOT NULL, status text NOT NULL DEFAULT 'Active', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(institution_id,number), UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS seat_pools(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), programme text NOT NULL, batch text NOT NULL, capacity integer NOT NULL CHECK(capacity>=0), occupied integer NOT NULL DEFAULT 0 CHECK(occupied>=0 AND occupied<=capacity), UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS applications(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), external_ref text NOT NULL, name text NOT NULL, email text NOT NULL, programme text NOT NULL, batch text NOT NULL, department text NOT NULL, pool_id text NOT NULL, status text NOT NULL DEFAULT 'Submitted', eligibility_verified boolean NOT NULL DEFAULT false, allotment_verified boolean NOT NULL DEFAULT false, payment_verified boolean NOT NULL DEFAULT false, waiver_reason text, verifier_id text REFERENCES users(id), approver_id text REFERENCES users(id), student_id text, reason text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(institution_id,external_ref), FOREIGN KEY(institution_id,pool_id) REFERENCES seat_pools(institution_id,id), FOREIGN KEY(institution_id,student_id) REFERENCES students(institution_id,id), UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS competencies(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), code text NOT NULL, title text NOT NULL, subject text NOT NULL, curriculum_version text NOT NULL, source text NOT NULL, UNIQUE(institution_id,code,curriculum_version), UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS teaching_sessions(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), title text NOT NULL, department text NOT NULL, cohort text NOT NULL, faculty_id text NOT NULL, competency_id text NOT NULL, room text NOT NULL, category text NOT NULL CHECK(category IN ('Theory','Practical','Posting')), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'Planned' CHECK(status IN ('Planned','Conducted','Finalized','Cancelled')), version integer NOT NULL DEFAULT 1, CHECK(ends_at>starts_at), FOREIGN KEY(institution_id,faculty_id) REFERENCES users(institution_id,id), FOREIGN KEY(institution_id,competency_id) REFERENCES competencies(institution_id,id), UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS attendance(institution_id text NOT NULL, session_id text NOT NULL, student_id text NOT NULL, status text NOT NULL CHECK(status IN ('Present','Absent','Excused')), PRIMARY KEY(session_id,student_id), FOREIGN KEY(institution_id,session_id) REFERENCES teaching_sessions(institution_id,id), FOREIGN KEY(institution_id,student_id) REFERENCES students(institution_id,id));
CREATE TABLE IF NOT EXISTS corrections(id text PRIMARY KEY, institution_id text NOT NULL, session_id text NOT NULL, student_id text NOT NULL, proposed_status text NOT NULL CHECK(proposed_status IN ('Present','Absent','Excused')), reason text NOT NULL, requester_id text NOT NULL REFERENCES users(id), approver_id text REFERENCES users(id), status text NOT NULL DEFAULT 'Pending', version integer NOT NULL DEFAULT 1, FOREIGN KEY(institution_id,session_id) REFERENCES teaching_sessions(institution_id,id), FOREIGN KEY(institution_id,student_id) REFERENCES students(institution_id,id));
CREATE TABLE IF NOT EXISTS assessments(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), title text NOT NULL, department text NOT NULL, cohort text NOT NULL, competency_id text NOT NULL, max_marks integer NOT NULL CHECK(max_marks>0), examiner_id text NOT NULL, creator_id text NOT NULL, moderator_id text, publisher_id text, status text NOT NULL DEFAULT 'Draft', version integer NOT NULL DEFAULT 1, rubric text NOT NULL, snapshot jsonb, published_at timestamptz, FOREIGN KEY(institution_id,examiner_id) REFERENCES users(institution_id,id), FOREIGN KEY(institution_id,competency_id) REFERENCES competencies(institution_id,id), UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS marks(institution_id text NOT NULL, assessment_id text NOT NULL, student_id text NOT NULL, score integer CHECK(score>=0), state text NOT NULL CHECK(state IN ('Scored','Absent','Withheld','Not assessed')), entered_by text NOT NULL REFERENCES users(id), PRIMARY KEY(assessment_id,student_id), FOREIGN KEY(institution_id,assessment_id) REFERENCES assessments(institution_id,id), FOREIGN KEY(institution_id,student_id) REFERENCES students(institution_id,id), CHECK((state='Scored' AND score IS NOT NULL) OR (state<>'Scored' AND score IS NULL)));
CREATE TABLE IF NOT EXISTS logbook(id text PRIMARY KEY, institution_id text NOT NULL, student_id text NOT NULL, competency_id text NOT NULL, supervisor_id text NOT NULL, activity text NOT NULL, activity_date date NOT NULL, reflection text NOT NULL, posting text NOT NULL, status text NOT NULL DEFAULT 'Submitted', review_note text, version integer NOT NULL DEFAULT 1, reviewed_by text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(institution_id,student_id) REFERENCES students(institution_id,id), FOREIGN KEY(institution_id,competency_id) REFERENCES competencies(institution_id,id), FOREIGN KEY(institution_id,supervisor_id) REFERENCES users(institution_id,id));
CREATE TABLE IF NOT EXISTS invoices(id text PRIMARY KEY, institution_id text NOT NULL, student_id text NOT NULL, description text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), paid_minor integer NOT NULL DEFAULT 0 CHECK(paid_minor>=0 AND paid_minor<=amount_minor), currency text NOT NULL DEFAULT 'INR', due_date date NOT NULL, fee_version text NOT NULL, status text NOT NULL DEFAULT 'Due', version integer NOT NULL DEFAULT 1, FOREIGN KEY(institution_id,student_id) REFERENCES students(institution_id,id), UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS payments(id text PRIMARY KEY, institution_id text NOT NULL, invoice_id text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), reference text NOT NULL, method text NOT NULL, actor_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(institution_id,reference), FOREIGN KEY(institution_id,invoice_id) REFERENCES invoices(institution_id,id), UNIQUE(institution_id,id));
CREATE TABLE IF NOT EXISTS refunds(id text PRIMARY KEY, institution_id text NOT NULL, payment_id text NOT NULL, amount_minor integer NOT NULL CHECK(amount_minor>0), reason text NOT NULL, requester_id text NOT NULL REFERENCES users(id), approver_id text REFERENCES users(id), status text NOT NULL DEFAULT 'Pending approval', version integer NOT NULL DEFAULT 1, FOREIGN KEY(institution_id,payment_id) REFERENCES payments(institution_id,id));
CREATE TABLE IF NOT EXISTS content(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), slug text NOT NULL, title text NOT NULL, body text NOT NULL, kind text NOT NULL, language text NOT NULL DEFAULT 'en', status text NOT NULL DEFAULT 'Draft', owner_id text NOT NULL REFERENCES users(id), reviewer_id text REFERENCES users(id), review_date date NOT NULL, version integer NOT NULL DEFAULT 1, published_body text, published_title text, published_at timestamptz, UNIQUE(institution_id,slug,language));
CREATE TABLE IF NOT EXISTS tickets(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), title text NOT NULL, description text NOT NULL, requester_id text NOT NULL REFERENCES users(id), assigned_to text REFERENCES users(id), confidential boolean NOT NULL DEFAULT false, severity text NOT NULL DEFAULT 'Normal', due_date date NOT NULL, status text NOT NULL DEFAULT 'Open', resolution text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notices(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), title text NOT NULL, body text NOT NULL, audience text NOT NULL, owner_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), owner_id text NOT NULL REFERENCES users(id), name text NOT NULL, mime text NOT NULL, size integer NOT NULL CHECK(size<=5242880), checksum text NOT NULL, status text NOT NULL DEFAULT 'Quarantined', content_base64 text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), title text NOT NULL, period text NOT NULL, owner_id text NOT NULL REFERENCES users(id), checksum text NOT NULL, manifest jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), actor_id text NOT NULL REFERENCES users(id), action text NOT NULL, entity_id text NOT NULL, reason text, previous jsonb, correlation_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), event_type text NOT NULL, entity_id text NOT NULL, status text NOT NULL DEFAULT 'Pending', attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency(institution_id text NOT NULL, actor_id text NOT NULL, operation text NOT NULL, key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, PRIMARY KEY(institution_id,actor_id,operation,key));
CREATE INDEX IF NOT EXISTS student_scope ON students(institution_id,batch,department);
CREATE INDEX IF NOT EXISTS session_scope ON teaching_sessions(institution_id,starts_at,faculty_id);
CREATE INDEX IF NOT EXISTS audit_scope ON audit(institution_id,created_at);
CREATE INDEX IF NOT EXISTS ticket_scope ON tickets(institution_id,requester_id,confidential);
